#!/usr/bin/env bash
# Render runtime secrets from AWS Secrets Manager into tmpfs (never onto disk, never into Git).
#
#   render-secrets.sh                  # reads GOSSY_SECRET_ID / GOSSY_AWS_REGION from /etc/gossy/gossy.env
#   render-secrets.sh --from-file F    # LOCAL REHEARSAL ONLY: same JSON document from a file
#
# Secret document (JSON, generated by Terraform - see deploy/aws/terraform/secrets.tf):
#   db_postgres_password, db_owner_password, db_app_password,
#   mqtt_svc_ingest_password, mqtt_svc_health_password, jwt_signing_key, otp_hmac_key,
#   [staging only] test_otp_code, mqtt_test_devices {"<device-id>": "<password>"}
#
# Layout - each consumer mounts ONLY its own directory, files are 0400:
#   /run/gossy-secrets/db/        postgres (uid 70): postgres/owner/app passwords (role init)
#   /run/gossy-secrets/app/       api + ingest (uid 10001): db/app.password, auth/*, mqtt/svc-ingest.password
#   /run/gossy-secrets/migrate/   migrations (uid 10001): db/owner.password
#   /run/gossy-secrets/mqtt/      broker init (root): <account>.password
#   /run/gossy-secrets/health/    broker healthcheck (uid 1883): svc-health.password
set -euo pipefail

ROOT=${GOSSY_SECRETS_ROOT:-/run/gossy-secrets}
ENV_FILE=${GOSSY_ENV_FILE:-/etc/gossy/gossy.env}
PG_UID=70      # postgres user in timescale/timescaledb (alpine)
APP_UID=10001  # gossy user in the backend image
MQTT_UID=1883  # mosquitto user in eclipse-mosquitto

[ -f "$ENV_FILE" ] && set -a && . "$ENV_FILE" && set +a

if [ "${1:-}" = "--from-file" ]; then
  DOC=$(cat "$2")
else
  : "${GOSSY_SECRET_ID:?GOSSY_SECRET_ID not set}" "${GOSSY_AWS_REGION:?}"
  DOC=$(aws secretsmanager get-secret-value --region "$GOSSY_AWS_REGION" --secret-id "$GOSSY_SECRET_ID" --query SecretString --output text)
fi

if ! mountpoint -q "$ROOT" 2>/dev/null; then
  mkdir -p "$ROOT"
  mount -t tmpfs -o size=4m,mode=0711,nodev,nosuid,noexec tmpfs "$ROOT"
fi
umask 077
# The document is passed in the environment (readable by root only), not as an argument.
GOSSY_SECRET_DOC="$DOC" GOSSY_SECRETS_ROOT="$ROOT" GOSSY_ENVIRONMENT="${GOSSY_ENVIRONMENT:?}" PG_UID=$PG_UID APP_UID=$APP_UID MQTT_UID=$MQTT_UID python3 - <<'PY'
import hashlib, json, os, re, sys
raw = os.environ["GOSSY_SECRET_DOC"]
doc = json.loads(raw)
root, env = os.environ["GOSSY_SECRETS_ROOT"], os.environ["GOSSY_ENVIRONMENT"]
pg, app, mqtt = int(os.environ["PG_UID"]), int(os.environ["APP_UID"]), int(os.environ["MQTT_UID"])

# Validate BEFORE touching what is already rendered: a refused document must leave the
# running stack's secrets in place.
required = ["db_postgres_password", "db_owner_password", "db_app_password", "mqtt_svc_ingest_password",
            "mqtt_svc_health_password", "jwt_signing_key", "otp_hmac_key"]
missing = [k for k in required if not doc.get(k)]
if missing:
    sys.exit(f"secret document is missing: {missing}")
if any(str(v).startswith("devonly-") for v in doc.values() if isinstance(v, str)):
    sys.exit("refusing development secrets")
if env == "production" and (doc.get("test_otp_code") or doc.get("mqtt_test_devices")):
    sys.exit("test OTP code / test devices are not allowed in production")
for device in doc.get("mqtt_test_devices") or {}:
    if not re.fullmatch(r"(sim|stg)-[a-z0-9-]{2,59}", device):
        sys.exit(f"test device ids must start with sim- or stg-: {device!r}")

# Replace FILES only: running containers bind-mount the per-consumer directories, which must
# stay the same directories across re-renders (rotation).
for folder, _dirs, files in os.walk(root):
    for name in files:
        os.remove(os.path.join(folder, name))

def put(rel, value, uid):
    path = os.path.join(root, rel)
    os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
    with open(path, "w") as f:
        f.write(str(value))
    os.chmod(path, 0o400)
    os.chown(path, uid, uid)

put("db/postgres.password", doc["db_postgres_password"], pg)
put("db/owner.password", doc["db_owner_password"], pg)
put("db/app.password", doc["db_app_password"], pg)
put("app/db/app.password", doc["db_app_password"], app)
put("app/auth/jwt-signing.key", doc["jwt_signing_key"], app)
put("app/auth/otp-hmac.key", doc["otp_hmac_key"], app)
put("app/mqtt/svc-ingest.password", doc["mqtt_svc_ingest_password"], app)
put("migrate/db/owner.password", doc["db_owner_password"], app)
put("mqtt/svc-ingest.password", doc["mqtt_svc_ingest_password"], 0)
put("mqtt/svc-health.password", doc["mqtt_svc_health_password"], 0)
put("health/svc-health.password", doc["mqtt_svc_health_password"], mqtt)
if doc.get("test_otp_code"):
    put("app/auth/test-otp.code", doc["test_otp_code"], app)
for device, password in (doc.get("mqtt_test_devices") or {}).items():
    put(f"mqtt/{device}.password", password, 0)

# Directory ownership: each consumer can traverse only its own tree.
for rel, uid in (("db", pg), ("app", app), ("app/db", app), ("app/auth", app), ("app/mqtt", app), ("migrate", app), ("migrate/db", app), ("mqtt", 0), ("health", mqtt)):
    os.chown(os.path.join(root, rel), uid, uid)
    os.chmod(os.path.join(root, rel), 0o500)
# Revision of this secret set (truncated SHA-256; reveals nothing). bin/deploy.sh passes it to
# the containers that hold credentials, so a rotation recreates exactly those containers.
with open(os.path.join(root, ".revision"), "w") as f:
    f.write(hashlib.sha256(raw.encode()).hexdigest()[:16])
os.chmod(os.path.join(root, ".revision"), 0o444)
print(f"secrets rendered for {env}: {sorted(k for k in doc if k != 'mqtt_test_devices')} "
      f"+ {len(doc.get('mqtt_test_devices') or {})} test device(s)")
PY
